const { existsSync, readFileSync } = await import('node:fs');
if (!input.image_path) throw new Error('Missing required input: image_path');
if (!existsSync(input.image_path)) throw new Error(`Image file not found at ${input.image_path}`);
globalThis.imageBuffer = readFileSync(input.image_path);

const mod = await import('pdf-lib');
const pdfLib = mod.default || mod;
const { PDFDocument } = pdfLib;
const pdfDoc = await PDFDocument.create();
const img = await pdfDoc.embedPng(globalThis.imageBuffer);
const { width, height } = img;
const page = pdfDoc.addPage([width, height]);
page.drawImage(img, { x: 0, y: 0, width, height });
globalThis.pdfBytes = await pdfDoc.save();

const { Buffer } = await import('node:buffer');
const base64 = Buffer.from(globalThis.pdfBytes).toString('base64');
console.log(JSON.stringify({ pdf_base64: base64 }));
